files.install-oaiy-voice.ps1:
# install-oaiy-voice.ps1
#
# The models OAIY's voice server (oaiy-voice) runs for calls:
#   - parakeet-tdt-0.6b-v2        speech to text (NVIDIA, CC-BY-4.0)
#   - Qwen3-TTS-12Hz-0.6B-Base    text to speech in a voice from a clip (Qwen, Apache-2.0)
#
# Each is used where it already is, in any of OAIY's model folders (Settings >
# model folders); otherwise it is downloaded into the primary one from Hugging
# Face at a pinned revision, and its large files are checked against their
# SHA-256 before the folder is put in place.
$ErrorActionPreference = 'Stop'

$modelsDir = $env:OAIY_MODELS_DIR
if (-not $modelsDir) {
  if (-not $env:OAIY_DATA_DIR) { throw "OAIY_MODELS_DIR is not set" }
  $modelsDir = Join-Path $env:OAIY_DATA_DIR 'models'
}
$roots = @($modelsDir)
if ($env:OAIY_MODEL_DIRS) { $roots += $env:OAIY_MODEL_DIRS -split [IO.Path]::PathSeparator | Where-Object { $_ } }

$models = @(
  @{
    name = 'parakeet-tdt-0.6b-v2'; repo = 'nvidia/parakeet-tdt-0.6b-v2'; revision = 'ae9ad07059c7c739ffaf932226a8fe64ae2620b0'
    license = 'CC-BY-4.0 (https://huggingface.co/nvidia/parakeet-tdt-0.6b-v2)'
    files = @(
      @{ path = 'parakeet-tdt-0.6b-v2.nemo'; sha256 = 'd99e39955c9d3d0350d8fb7c75e40c64a2b2eaeb003883d7c941fd2e8747b28c' }
    )
  },
  @{
    name = 'Qwen3-TTS-12Hz-0.6B-Base'; repo = 'Qwen/Qwen3-TTS-12Hz-0.6B-Base'; revision = '5d83992436eae1d760afd27aff78a71d676296fc'
    license = 'Apache-2.0 (https://huggingface.co/Qwen/Qwen3-TTS-12Hz-0.6B-Base)'
    files = @(
      @{ path = 'config.json' }, @{ path = 'generation_config.json' }, @{ path = 'merges.txt' },
      @{ path = 'preprocessor_config.json' }, @{ path = 'tokenizer_config.json' }, @{ path = 'vocab.json' },
      @{ path = 'model.safetensors'; sha256 = '180b3b10eb1c9f1b4db7806d5475bae3071c0243c299d49926bab1da3b6946f6' },
      @{ path = 'speech_tokenizer/config.json' }, @{ path = 'speech_tokenizer/configuration.json' },
      @{ path = 'speech_tokenizer/preprocessor_config.json' },
      @{ path = 'speech_tokenizer/model.safetensors'; sha256 = '836b7b357f5ea43e889936a3709af68dfe3751881acefe4ecf0dbd30ba571258' }
    )
  }
)

function Test-Complete($dir, $model) {
  foreach ($f in $model.files) {
    if (-not (Test-Path (Join-Path $dir $f.path))) { return $false }
  }
  return $true
}

foreach ($m in $models) {
  $found = $roots | ForEach-Object { Join-Path $_ $m.name } | Where-Object { Test-Complete $_ $m } | Select-Object -First 1
  if ($found) {
    Write-Output "$($m.name): found at $found"
    continue
  }
  $dest = Join-Path $modelsDir $m.name
  $staging = "$dest.partial"
  New-Item -ItemType Directory -Force -Path $staging | Out-Null
  Write-Output "$($m.name): downloading from $($m.repo) - licence: $($m.license)"
  $oldPref = $ProgressPreference
  $ProgressPreference = 'SilentlyContinue'
  try {
    foreach ($f in $m.files) {
      $target = Join-Path $staging $f.path
      New-Item -ItemType Directory -Force -Path (Split-Path $target -Parent) | Out-Null
      $ok = (Test-Path $target) -and ((-not $f.sha256) -or (Get-FileHash $target -Algorithm SHA256).Hash.ToLower() -eq $f.sha256)
      if ($ok) { Write-Output "  ok (already here)  $($f.path)"; continue }
      $url = "https://huggingface.co/$($m.repo)/resolve/$($m.revision)/$($f.path)"
      Write-Output "  downloading  $($f.path)"
      Invoke-WebRequest -Uri $url -OutFile "$target.part" -UseBasicParsing -MaximumRedirection 10
      if ($f.sha256) {
        $digest = (Get-FileHash "$target.part" -Algorithm SHA256).Hash.ToLower()
        if ($digest -ne $f.sha256) {
          Remove-Item "$target.part" -Force
          throw "$($f.path): checksum mismatch - expected $($f.sha256), got $digest"
        }
      }
      Move-Item "$target.part" $target -Force
      Write-Output "  verified     $($f.path)"
    }
  } finally {
    $ProgressPreference = $oldPref
  }
  if (Test-Path $dest) { Remove-Item $dest -Recurse -Force }
  Move-Item $staging $dest -Force
  Write-Output "$($m.name): installed to $dest"
}

$marker = Join-Path $modelsDir 'oaiy-voice'
New-Item -ItemType Directory -Force -Path $marker | Out-Null
New-Item -ItemType File -Force -Path (Join-Path $marker '.oaiy-installed') | Out-Null
Write-Output "OAIY Voice is ready"
